"use client";

import * as React from "react";
type App = {
  id: string;
  name: string;
  vendor?: string;
  description: string;
  category?: string;
  categories: string[];
  icon?: string | React.ReactNode;
  logo?: string | React.ReactNode;
  connected?: boolean;
  essential?: boolean;
  color?: string;
  tile?: string;
};
type AppCategory = {
  id: string;
  label: string;
  icon?: React.ReactNode;
};
interface AppDirectoryProps {
  title?: string;
  subtitle?: string;
  apps?: App[];
  categories?: AppCategory[];
  onToggle?: (app: App, connected: boolean) => void;
  className?: string;
}
function AppDirectory({
  title = `Integrations`,
  subtitle = `Connect the tools your team already works in.`,
  apps = defaultApps,
  categories = defaultCategories,
  onToggle: onToggle,
  className: className,
}: AppDirectoryProps) {
  let [connectedIds, setConnectedIds] = React.useState(
      () => new Set(apps.filter((e) => e.connected).map((e) => e.id)),
    ),
    [busyIds, setBusyIds] = React.useState(new Set()),
    [category, setCategory] = React.useState(`essentials`),
    [query, setQuery] = React.useState(``),
    [status, setStatus] = React.useState(`all`),
    [menuOpen, setMenuOpen] = React.useState(false),
    filterRef = React.useRef<HTMLDivElement | null>(null),
    searchId = React.useId(),
    mainRef = React.useRef<HTMLDivElement | null>(null),
    morphRef = useHeightMorph(mainRef);
  React.useEffect(() => {
    if (!menuOpen) return;
    let e = (e: PointerEvent) =>
        !filterRef.current?.contains(e.target as Node | null) &&
        setMenuOpen(false),
      t = (e: { key: string }) => e.key === `Escape` && setMenuOpen(false);
    return (
      window.addEventListener(`pointerdown`, e),
      window.addEventListener(`keydown`, t),
      () => {
        (window.removeEventListener(`pointerdown`, e),
          window.removeEventListener(`keydown`, t));
      }
    );
  }, [menuOpen]);
  let matchesCategory = (app: App, categoryId: string) =>
      categoryId === `all`
        ? true
        : categoryId === `essentials`
          ? !!app.essential
          : app.categories.includes(categoryId),
    normalizedQuery = query.trim().toLowerCase(),
    visibleApps = React.useMemo(
      () =>
        apps.filter(
          (e) =>
            !(
              (normalizedQuery &&
                !`${e.name} ${e.vendor} ${e.description}`
                  .toLowerCase()
                  .includes(normalizedQuery)) ||
              (!normalizedQuery && !matchesCategory(e, category)) ||
              (status === `connected` && !connectedIds.has(e.id)) ||
              (status === `available` && connectedIds.has(e.id))
            ),
        ),
      [apps, normalizedQuery, category, status, connectedIds],
    ),
    toggleApp = (app: App) => {
      if (!busyIds.has(app.id)) {
        if (connectedIds.has(app.id)) {
          let t = new Set(connectedIds);
          (t.delete(app.id), setConnectedIds(t), onToggle?.(app, false));
          return;
        }
        (setBusyIds((t) => new Set(t).add(app.id)),
          window.setTimeout(() => {
            (setBusyIds((t) => {
              let n = new Set(t);
              return (n.delete(app.id), n);
            }),
              setConnectedIds((t) => new Set(t).add(app.id)),
              onToggle?.(app, true));
          }, 900));
      }
    },
    heading = normalizedQuery
      ? `Results for “${query.trim()}”`
      : (categories.find((e) => e.id === category)?.label ?? `Apps`),
    nonessentialApps = apps.filter((e) => !e.essential),
    showDiscover =
      !normalizedQuery &&
      category === `essentials` &&
      status === `all` &&
      nonessentialApps.length > 0,
    filterLabel = {
      all: `All apps`,
      connected: `Connected`,
      available: `Not connected`,
    }[status];
  return (
    <>
      <style href={`ui-app-directory`} precedence={`default`}>
        {appDirectoryStyles}
      </style>
      <section
        className={[`ui-ad`, className].filter(Boolean).join(` `)}
        aria-label={title}
      >
        <header className={`ui-ad__bar`}>
          <span className={`ui-ad__bar-title`}>{`Apps`}</span>
          <span className={`ui-ad__bar-meta`}>
            {connectedIds.size}
            {` connected`}
          </span>
        </header>
        <div className={`ui-ad__card`}>
          <div className={`ui-ad__intro`}>
            <h2 className={`ui-ad__title`}>{title}</h2>
            <p className={`ui-ad__subtitle`}>
              {subtitle}
              {` `}
              <a
                href={`#`}
                className={`ui-ad__link`}
                onClick={(e) => e.preventDefault()}
              >
                {`Learn more `}
                <ArrowUpRightIcon />
              </a>
            </p>
          </div>
          <div className={`ui-ad__tools`}>
            <label className={`ui-ad__search`} htmlFor={searchId}>
              <SearchIcon />
              <input
                id={searchId}
                type={`search`}
                placeholder={`Search apps`}
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                autoComplete={`off`}
              />
            </label>
            <div className={`ui-ad__filter`} ref={filterRef}>
              <button
                type={`button`}
                className={`ui-ad__btn`}
                aria-haspopup={`menu`}
                aria-expanded={menuOpen}
                data-active={status !== `all` || void 0}
                onClick={() => setMenuOpen((e) => !e)}
              >
                <FilterIcon />
                {status === `all` ? `Filter` : filterLabel}
              </button>
              {menuOpen && (
                <div className={`ui-ad__menu`} role={`menu`}>
                  {[`all`, `connected`, `available`].map((e) => (
                    <button
                      type={`button`}
                      role={`menuitemradio`}
                      aria-checked={status === e}
                      className={`ui-ad__menu-item`}
                      onClick={() => {
                        (setStatus(e), setMenuOpen(false));
                      }}
                      key={e}
                    >
                      {
                        {
                          all: `All apps`,
                          connected: `Connected`,
                          available: `Not connected`,
                        }[e]
                      }
                      {status === e && <CheckIcon />}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
          <div className={`ui-ad__layout`}>
            <nav className={`ui-ad__nav`} aria-label={`Categories`}>
              {categories.map((e) => {
                let t = apps.filter((t) => matchesCategory(t, e.id)).length,
                  n = !normalizedQuery && category === e.id;
                return (
                  <button
                    type={`button`}
                    className={`ui-ad__nav-item`}
                    aria-current={n || void 0}
                    onClick={() => {
                      (setCategory(e.id), setQuery(``));
                    }}
                    key={e.id}
                  >
                    <span className={`ui-ad__nav-icon`}>{e.icon}</span>
                    <span className={`ui-ad__nav-label`}>{e.label}</span>
                    <span className={`ui-ad__nav-count`}>{t}</span>
                  </button>
                );
              })}
            </nav>
            <div className={`ui-ad__morph`} ref={morphRef}>
              <div className={`ui-ad__main`} ref={mainRef}>
                <h3 className={`ui-ad__heading`} aria-live={`polite`}>
                  {heading}
                  <span>{visibleApps.length}</span>
                </h3>
                {visibleApps.length === 0 ? (
                  <div className={`ui-ad__empty`}>
                    <p>{`No apps match.`}</p>
                    <button
                      type={`button`}
                      className={`ui-ad__btn`}
                      onClick={() => {
                        (setQuery(``), setStatus(`all`));
                      }}
                    >{`Clear search`}</button>
                  </div>
                ) : (
                  <ul className={`ui-ad__grid`}>
                    {visibleApps.map((e, t) => {
                      let n = connectedIds.has(e.id),
                        i = busyIds.has(e.id);
                      return (
                        <li
                          className={`ui-ad__app`}
                          data-connected={n || void 0}
                          style={{
                            animationDelay: `${t * 30}ms`,
                          }}
                          key={e.id}
                        >
                          <div className={`ui-ad__app-head`}>
                            <span
                              className={`ui-ad__tile`}
                              data-filled={e.tile ? true : void 0}
                              style={
                                e.tile
                                  ? {
                                      background: e.tile,
                                    }
                                  : void 0
                              }
                            >
                              {e.logo}
                            </span>
                            <span className={`ui-ad__app-name`}>
                              <span className={`ui-ad__name`}>
                                {e.name}
                                <VerifiedIcon />
                              </span>
                              <span className={`ui-ad__vendor`}>
                                {`By `}
                                {e.vendor}
                              </span>
                            </span>
                          </div>
                          <p className={`ui-ad__desc`}>{e.description}</p>
                          <ConnectButton
                            name={e.name}
                            state={i ? `busy` : n ? `on` : `off`}
                            onClick={() => toggleApp(e)}
                          />
                        </li>
                      );
                    })}
                    {showDiscover && (
                      <li className={`ui-ad__app ui-ad__discover`}>
                        <div className={`ui-ad__discover-head`}>
                          <span>
                            <span
                              className={`ui-ad__name`}
                            >{`Discover more`}</span>
                            <span className={`ui-ad__vendor`}>
                              {`+`}
                              {nonessentialApps.length}
                              {` apps`}
                            </span>
                          </span>
                          <span className={`ui-ad__stack`} aria-hidden={`true`}>
                            {nonessentialApps.slice(0, 3).map((e) => (
                              <span
                                className={`ui-ad__tile`}
                                data-filled={e.tile ? true : void 0}
                                style={
                                  e.tile
                                    ? {
                                        background: e.tile,
                                      }
                                    : void 0
                                }
                                key={e.id}
                              >
                                {e.logo}
                              </span>
                            ))}
                          </span>
                        </div>
                        <button
                          type={`button`}
                          className={`ui-ad__btn`}
                          onClick={() => setCategory(`all`)}
                        >{`View all`}</button>
                      </li>
                    )}
                  </ul>
                )}
              </div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}
function ConnectButton({
  name: name,
  state: state,
  onClick: onClick,
}: {
  name: string;
  state: "on" | "busy" | "off";
  onClick: () => void;
}) {
  let buttonRef = React.useRef<HTMLButtonElement | null>(null),
    labelRef = React.useRef<HTMLSpanElement | null>(null);
  return (
    React.useLayoutEffect(() => {
      let e = buttonRef.current,
        t = labelRef.current;
      if (!e || !t) return;
      let n =
          parseFloat(getComputedStyle(e).paddingLeft) +
          parseFloat(getComputedStyle(e).paddingRight),
        r = () => {
          e.style.width = `${t.offsetWidth + n}px`;
        };
      r();
      let i = new ResizeObserver(r);
      i.observe(t);
      let s = requestAnimationFrame(() => e.setAttribute(`data-smooth`, ``));
      return () => {
        (i.disconnect(), cancelAnimationFrame(s));
      };
    }, []),
    (
      <button
        ref={buttonRef}
        type={`button`}
        className={`ui-ad__connect`}
        data-state={state}
        aria-label={`${state === `on` ? `Disconnect` : `Connect`} ${name}`}
        onClick={onClick}
      >
        <span ref={labelRef} className={`ui-ad__connect-label`}>
          {state === `busy` ? (
            <>
              <Spinner />
              {` Connecting…`}
            </>
          ) : state === `on` ? (
            <>
              <LinkIcon />
              {` `}
              <span className={`ui-ad__on-label`}>{`Connected`}</span>
              <span className={`ui-ad__off-label`}>{`Disconnect`}</span>
            </>
          ) : (
            `Connect`
          )}
        </span>
      </button>
    )
  );
}
var strokeIcon = (path: string | undefined, size = 16) => (
  <svg
    viewBox={`0 0 16 16`}
    width={size}
    height={size}
    fill={`none`}
    stroke={`currentColor`}
    strokeWidth={`1.3`}
    strokeLinecap={`round`}
    strokeLinejoin={`round`}
    aria-hidden={`true`}
  >
    <path d={path} />
  </svg>
);
var SearchIcon = () =>
  strokeIcon(`M7 12.5a5.5 5.5 0 1 0 0-11 5.5 5.5 0 0 0 0 11ZM11 11l3.5 3.5`);
var FilterIcon = () => strokeIcon(`M2.5 4.5h11M4.5 8h7M6.5 11.5h3`);
var ArrowUpRightIcon = () => strokeIcon(`M5 11 11 5M6 5h5v5`, 12);
var CheckIcon = () => strokeIcon(`m3.5 8.5 3 3 6-7`, 14);
var LinkIcon = () =>
  strokeIcon(
    `M6.5 9.5l3-3M7.3 4.7l.9-.9a2.5 2.5 0 0 1 3.5 3.5l-.9.9M8.7 11.3l-.9.9a2.5 2.5 0 0 1-3.5-3.5l.9-.9`,
    14,
  );
var VerifiedIcon = () => (
  <svg
    className={`ui-ad__verified`}
    viewBox={`0 0 16 16`}
    width={`15`}
    height={`15`}
    role={`img`}
    aria-label={`Verified`}
  >
    <path
      d={`M8.00 0.80 L9.55 2.20 L11.60 1.76 L12.24 3.76 L14.24 4.40 L13.80 6.45 L15.20 8.00 L13.80 9.55 L14.24 11.60 L12.24 12.24 L11.60 14.24 L9.55 13.80 L8.00 15.20 L6.45 13.80 L4.40 14.24 L3.76 12.24 L1.76 11.60 L2.20 9.55 L0.80 8.00 L2.20 6.45 L1.76 4.40 L3.76 3.76 L4.40 1.76 L6.45 2.20Z`}
      fill={`currentColor`}
      stroke={`currentColor`}
      strokeWidth={`1.2`}
      strokeLinejoin={`round`}
    />
    <path
      d={`m5.3 8.1 1.8 1.8 3.6-3.7`}
      fill={`none`}
      stroke={`var(--ui-ad-on-accent, #fff)`}
      strokeWidth={`1.5`}
      strokeLinecap={`round`}
      strokeLinejoin={`round`}
    />
  </svg>
);
var Spinner = () => <span className={`ui-ad__spinner`} aria-hidden={`true`} />;
var categoryIcons = {
  essentials: strokeIcon(
    `m8 1.8 1.9 3.9 4.3.6-3.1 3 .7 4.3L8 11.6l-3.8 2 .7-4.3-3.1-3 4.3-.6Z`,
  ),
  all: strokeIcon(
    `M2.5 2.5h4v4h-4zM9.5 2.5h4v4h-4zM2.5 9.5h4v4h-4zM9.5 9.5h4v4h-4z`,
  ),
  analytics: strokeIcon(
    `M2.5 2.5h11v11h-11zM5.5 10.5v-2M8 10.5v-5M10.5 10.5V7`,
  ),
  automation: strokeIcon(`M9 1.5 3.5 9H8l-1 5.5L12.5 7H8Z`),
  billing: strokeIcon(
    `M8 14.5a6.5 6.5 0 1 0 0-13 6.5 6.5 0 0 0 0 13ZM10 5.8C9.6 5.2 8.9 5 8 5c-1.1 0-2 .6-2 1.5S6.9 7.8 8 8s2 .6 2 1.5S9.1 11 8 11c-.9 0-1.7-.3-2.1-1M8 3.8V5M8 11v1.2`,
  ),
  communication: strokeIcon(`M2.5 3.5h11v7.5H7l-3 2.5V11H2.5Z`),
  crm: strokeIcon(
    `M6 7.5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5ZM1.5 13.5c.6-2.3 2.3-3.5 4.5-3.5s3.9 1.2 4.5 3.5M10.5 2.7a2.5 2.5 0 0 1 0 4.6M12.5 10.3c1 .6 1.7 1.6 2 3.2`,
  ),
  design: strokeIcon(`M10.5 2.5 13.5 5.5 6 13H3v-3ZM9 4l3 3`),
  development: strokeIcon(`M5.5 4.5 2 8l3.5 3.5M10.5 4.5 14 8l-3.5 3.5`),
  docs: strokeIcon(`M4 1.5h5.5l3 3v10H4zM9.5 1.5v3h3M6 8h4.5M6 10.5h4.5`),
  product: strokeIcon(`M2.5 2.5h3v11h-3zM6.5 2.5h3v7h-3zM10.5 2.5h3v4h-3z`),
  scheduling: strokeIcon(`M2.5 3.5h11v10h-11zM2.5 6.5h11M5.5 1.5v3M10.5 1.5v3`),
  storage: strokeIcon(
    `M2.5 4c0-1.1 2.5-2 5.5-2s5.5.9 5.5 2-2.5 2-5.5 2-5.5-.9-5.5-2ZM2.5 4v8c0 1.1 2.5 2 5.5 2s5.5-.9 5.5-2V4M2.5 8c0 1.1 2.5 2 5.5 2s5.5-.9 5.5-2`,
  ),
};
var defaultCategories = [
  {
    id: `essentials`,
    label: `Essentials`,
    icon: categoryIcons.essentials,
  },
  {
    id: `all`,
    label: `All apps`,
    icon: categoryIcons.all,
  },
  {
    id: `analytics`,
    label: `Analytics`,
    icon: categoryIcons.analytics,
  },
  {
    id: `automation`,
    label: `Automation`,
    icon: categoryIcons.automation,
  },
  {
    id: `billing`,
    label: `Billing`,
    icon: categoryIcons.billing,
  },
  {
    id: `communication`,
    label: `Communication`,
    icon: categoryIcons.communication,
  },
  {
    id: `crm`,
    label: `CRM`,
    icon: categoryIcons.crm,
  },
  {
    id: `design`,
    label: `Design`,
    icon: categoryIcons.design,
  },
  {
    id: `development`,
    label: `Development`,
    icon: categoryIcons.development,
  },
  {
    id: `docs`,
    label: `Docs`,
    icon: categoryIcons.docs,
  },
  {
    id: `product`,
    label: `Product`,
    icon: categoryIcons.product,
  },
  {
    id: `scheduling`,
    label: `Scheduling`,
    icon: categoryIcons.scheduling,
  },
  {
    id: `storage`,
    label: `Storage`,
    icon: categoryIcons.storage,
  },
];
var appLogoPath = (path: string | undefined, fill: string | undefined) => (
  <svg viewBox={`0 0 24 24`} fill={fill} aria-hidden={`true`}>
    <path d={path} />
  </svg>
);
const View_InlineView = () => (
  <svg viewBox={`0 0 24 24`} aria-hidden={`true`}>
    <path
      fill={`#E01E5A`}
      d={`M5.04 15.17a2.53 2.53 0 0 1-2.52 2.52A2.53 2.53 0 0 1 0 15.17a2.53 2.53 0 0 1 2.52-2.53h2.52zm1.27 0a2.53 2.53 0 0 1 2.53-2.53 2.53 2.53 0 0 1 2.52 2.53v6.31A2.53 2.53 0 0 1 8.84 24a2.53 2.53 0 0 1-2.53-2.52z`}
    />
    <path
      fill={`#36C5F0`}
      d={`M8.84 5.04a2.53 2.53 0 0 1-2.53-2.52A2.53 2.53 0 0 1 8.84 0a2.53 2.53 0 0 1 2.52 2.52v2.52zm0 1.27a2.53 2.53 0 0 1 2.52 2.53 2.53 2.53 0 0 1-2.52 2.52H2.52A2.53 2.53 0 0 1 0 8.84a2.53 2.53 0 0 1 2.52-2.53z`}
    />
    <path
      fill={`#2EB67D`}
      d={`M18.96 8.84a2.53 2.53 0 0 1 2.52-2.53A2.53 2.53 0 0 1 24 8.84a2.53 2.53 0 0 1-2.52 2.52h-2.52zm-1.27 0a2.53 2.53 0 0 1-2.53 2.52 2.53 2.53 0 0 1-2.52-2.52V2.52A2.53 2.53 0 0 1 15.16 0a2.53 2.53 0 0 1 2.53 2.52z`}
    />
    <path
      fill={`#ECB22E`}
      d={`M15.16 18.96a2.53 2.53 0 0 1 2.53 2.52A2.53 2.53 0 0 1 15.16 24a2.53 2.53 0 0 1-2.52-2.52v-2.52zm0-1.27a2.53 2.53 0 0 1-2.52-2.53 2.53 2.53 0 0 1 2.52-2.52h6.32A2.53 2.53 0 0 1 24 15.16a2.53 2.53 0 0 1-2.52 2.53z`}
    />
  </svg>
);
const View_InlineView2 = () => (
  <svg viewBox={`0 0 38 57`} aria-hidden={`true`}>
    <path
      d={`M19 28.5a9.5 9.5 0 1 1 19 0 9.5 9.5 0 0 1-19 0Z`}
      fill={`#1ABCFE`}
    />
    <path
      d={`M0 47.5A9.5 9.5 0 0 1 9.5 38H19v9.5a9.5 9.5 0 1 1-19 0Z`}
      fill={`#0ACF83`}
    />
    <path d={`M19 0v19h9.5a9.5 9.5 0 1 0 0-19H19Z`} fill={`#FF7262`} />
    <path
      d={`M0 9.5A9.5 9.5 0 0 0 9.5 19H19V0H9.5A9.5 9.5 0 0 0 0 9.5Z`}
